// Hebrew is this fork's own proofer: upstream's `ProofLang` has no Hebrew, and reads a Hebrew
// `w:lang` as a language pack with no dictionary (no marks at all). Its runs go to
// `wordcraft-proof-he` and the rest to upstream's checker, so none is checked twice.
let spans: Vec<(std::ops::Range<usize>, wordcraft_proof::ProofLang)> =
    runs.iter().filter(|r| !is_hebrew(r.lang)).map(|r| (r.range.clone(), r.lang)).collect();

let mut issues = wordcraft_proof::check_text_with(&text, &spans, spelling, grammar, list_item);
let hebrew: Vec<std::ops::Range<usize>> = runs.iter().filter(|r| is_hebrew(r.lang) && !r.skip).map(|r| r.range.clone()).collect();
for range in hebrew {
    issues.extend(wordcraft_proof_he::issues(&text, range, spelling, grammar));
}
issues.sort_by_key(|i| (i.start, i.end));

