/// This fork opens in Hebrew, and Hebrew is one row of File ▸ Options ▸ Interface language like
/// every other language. A settings file that never chose a language moves to it; a choice
/// (`Automatic` included) is kept.
#[test]
fn this_fork_opens_in_hebrew_and_offers_hebrew_in_the_language_list() {
    needs_catalogs!();
    if !offers_hebrew() {
        return;
    }
    assert_eq!(DEFAULT_LANGUAGE, "he");
    let he = lang(DEFAULT_LANGUAGE);
    assert!(he.rtl(), "Hebrew mirrors the interface");
    assert_eq!(he.name(), "עברית", "the picker shows it under its own name");
    assert!(Lang::for_picker().iter().any(|l| l.code() == DEFAULT_LANGUAGE), "Hebrew is in the picker");

    // A settings file from a version before `languageChosen`: `auto` was written on the first run
    // whether or not anyone had chosen, so such a profile opens in Hebrew.
    let old = "{\"tab\":\"Home\",\"language\":\"auto\"}";
    let mut app = crate::WordApp::new(wordcraft_engine::Session::new(wordcraft_doc::Document::new()), Default::default());
    app.apply_prefs(serde_json::from_str(old).unwrap());
    assert_eq!(app.ui.language, DEFAULT_LANGUAGE);
    assert_eq!(Lang::from_pref(&app.ui.language), he);

    // A choice is kept, and choosing `Automatic` records one, so `auto` survives a restart.
    let chosen = "{\"language\":\"auto\",\"languageChosen\":true}";
    let mut fresh = crate::WordApp::new(wordcraft_engine::Session::new(wordcraft_doc::Document::new()), Default::default());
    fresh.apply_prefs(serde_json::from_str(chosen).unwrap());
    assert_eq!(fresh.ui.language, AUTO, "the user's Automatic stays automatic");
    assert!(!app.ui.language_chosen, "a new window has not chosen a language");
    app.run("ui.language", serde_json::json!({"value": "auto"})).unwrap();
    assert!(app.ui.language_chosen, "picking Automatic is a choice");
    let restored: crate::prefs::Prefs = serde_json::from_str(&serde_json::to_string(&app.ui).unwrap()).unwrap();
    assert_eq!(restored.language, AUTO);
    apply_language(Lang::EN);
}

